<?php require __DIR__.'/bootstrap.php';verify_csrf();if(isset($_GET['add'])){add_cart((int)$_GET['add'],1);flash('ok','محصول به سبد اضافه شد.');redirect('cart.php');}if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['add']))add_cart((int)$_POST['add'],(int)($_POST['qty']??1));if(isset($_POST['update'])){foreach($_POST['qty']??[] as $id=>$q){if((int)$q<=0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=(int)$q;}}if(isset($_POST['remove']))unset($_SESSION['cart'][(int)$_POST['remove']]);flash('ok','سبد خرید بروزرسانی شد.');redirect('cart.php');}$title='سبد خرید';require __DIR__.'/partials/header.php';$items=cart_items();?>
<h1>سبد خرید</h1><?php if(!$items): ?><div class="panel empty"><h2>سبد خرید خالی است</h2><a class="btn" href="<?=url('shop.php')?>">رفتن به فروشگاه</a></div><?php else: ?><div class="two-col"><div class="panel"><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><?php foreach($items as $p): ?><div class="cart-row"><img class="thumb" src="<?=e($p['image']?:'https://placehold.co/300x300?text=SHOPX')?>"><div><h3><?=e($p['name'])?></h3><div class="price"><?=money($p['price'])?></div></div><div class="qty"><label>تعداد</label><input type="number" name="qty[<?=$p['id']?>]" value="<?=$p['qty']?>" min="0" max="<?=$p['stock']?>"></div><div><?=money($p['line'])?></div><button class="btn red small" name="remove" value="<?=$p['id']?>">حذف</button></div><?php endforeach; ?><button class="btn outline" name="update">بروزرسانی سبد</button></form></div><div class="panel summary"><h2>خلاصه</h2><p>جمع کالاها: <b><?=money(cart_total())?></b></p><a class="btn" href="<?=url('checkout.php')?>">ادامه و ثبت سفارش</a></div></div><?php endif; ?>
<?php require __DIR__.'/partials/footer.php'; ?>
